    if (difference > 0) {
        jquery(".tooldrag").css("cssText", "height:" + (26 + difference) + "px!important");
    }
    //实现提示框拖拽功能
    jquery('.tooldrag').mousedown(function(e) {
        // e.pageX
        var positionDiv = jquery(this).offset();
        var distanceX = e.pageX - positionDiv.left;
        var distanceY = e.pageY - positionDiv.top;
        //alert(distanceX)
        // alert(positionDiv.left);

        jquery(document).mousemove(function(e) {
            var x = e.clientX - distanceX;
            var y = e.clientY - distanceY;

            if (x < 0) {
                x = 0;
            } else if (x > window.innerWidth - jquery('.tooldrag').outerWidth(true)) {
                x = window.innerWidth - jquery('.tooldrag').outerWidth(true);
            }

            if (y < 0) {
                y = 0;
            } else if (y > window.innerHeight - jquery('.tooldrag').outerHeight(true)) {
                y = window.innerHeight - jquery('.tooldrag').outerHeight(true);
            }

            jquery('.tooltips').css({
                'right': window.innerWidth - x - jquery('.tooltips').outerWidth(true) + 'px',
                'bottom': window.innerHeight - y - jquery('.tooltips').outerHeight(true) + 'px',
            });
        });

        jquery(document).mouseup(function() {
            jquery(document).off('mousemove');
        });
    });
    // 拖拽右下角改变大小
    const wrapperToolkit = document.getElementById('wrapperToolkit');
    const EasySpiderResizer = document.getElementById('EasySpiderResizer');

    let mousedown = false;
    let startX, startY, startWidth, startHeight;


    EasySpiderResizer.addEventListener('mousedown', e => {
        mousedown = true;
        startX = e.clientX;
        startY = e.clientY;
        startWidth = wrapperToolkit.offsetWidth;
        startHeight = wrapperToolkit.offsetHeight;
        e.preventDefault();
    });

    window.addEventListener('mousemove', e => {
        // if the mouse is not pressed, do nothing
        if (!mousedown) return;
        let newX = e.clientX;
        let newY = e.clientY;

        // Update the width: Original width - (current mouse X position - original mouse X position)
        let newWidth = startWidth - (newX - startX);

        // Update the height: Original height - (current mouse Y position - original mouse Y position)
        let newHeight = startHeight - (newY - startY);

