    }
    // console.log("------");
    // for (i = 0; i < global.nodeList.length; i++) {
    //     console.log(global.nodeList[i]["xpath"]);
    // }
    //对于可点击元素，屏蔽a标签默认点击事件
    event.stopImmediatePropagation();
