              "Can't set DOCTYPE here.  (Meteor sets <!DOCTYPE html> for you)");
          case '{{!':
            this.throwCompileError(
              "Can't use '{{! }}' outside a template.  Use '<!-- -->'.");
        }

        this.throwCompileError();
      }

