getCurrentGroupName = () => {
  try {
    const gid = userInfo().gid;
    const lines = readFileSync('/etc/group', 'utf8').split('\n');
    const match = lines.find(line => parseInt(line.split(':')[2], 10) === gid);
    return match ? match.split(':')[0] : null;
  } catch (_) {
    return null;
  }
}

getGroupToUse = () => {
  if (isMacOS()) {
