    .replace(/\/$/, '')
    .replace(/^https?:\/\//, '')
    .replace(/^git@github\.com:/, 'github.com/');
}

function buildForkUrl(owner) {
  // Match origin's protocol (SSH vs HTTPS)
  const originUrl = git('remote get-url origin', { silent: true }) || '';
  if (originUrl.startsWith('git@')) {
    return `git@github.com:${owner}/meteor.git`;
  }
  return `https://github.com/${owner}/meteor.git`;
}

async function main() {
  const args = process.argv.slice(2);

  // Ensure we're inside a git repo
  if (!git('rev-parse --is-inside-work-tree', { silent: true })) {
    die('not inside a git repository');
  }

  let forkOwner, forkBranch, forkRepoUrl;

  if (args.length === 1) {
    const arg = args[0];
    const prNumberMatch = arg.match(/^\d+$/);
    const prMatch = arg.match(/^https?:\/\/github\.com\/.*\/pull\/\d+/);
    const sshMatch = arg.match(/^git@[^:]+:/);
    const httpsRepoMatch = arg.match(/^https?:\/\/.*\.git$/);
    // user:branch — must not start with git@ (SSH) or contain / before : (URLs)
    const shortMatch = !sshMatch && arg.match(/^([^/:]+):(.+)$/);

    if (prNumberMatch) {
      const repoPath = getRepoPathFromOrigin();
      if (!repoPath) die('could not determine repository from origin remote');
      const prUrl = `https://github.com/${repoPath}/pull/${arg}`;
      info(`resolved PR #${arg} → ${c.bold}${prUrl}${c.reset}`);
      const result = await extractFromPrUrl(prUrl);
      forkOwner = result.owner;
      forkBranch = result.branch;
      forkRepoUrl = buildForkUrl(forkOwner);
    } else if (prMatch) {
      const result = await extractFromPrUrl(arg);
      forkOwner = result.owner;
      forkBranch = result.branch;
      forkRepoUrl = buildForkUrl(forkOwner);
    } else if (sshMatch || httpsRepoMatch) {
      die(`repo URL requires a branch argument: node scripts/checkout-pr.js ${arg} <branch>`);
    } else if (shortMatch) {
      forkOwner = shortMatch[1];
      forkBranch = shortMatch[2];
      forkRepoUrl = buildForkUrl(forkOwner);
    } else {
      err(`unrecognized format: ${arg}`);
      console.error('');
      return usage();
    }
  } else if (args.length === 2) {
    forkRepoUrl = args[0];
    forkBranch = args[1];
    forkOwner = extractOwnerFromUrl(forkRepoUrl);
    if (!forkOwner) die(`could not extract owner from URL: ${forkRepoUrl}`);
  } else {
    return usage();
  }

  const previousBranch = git('symbolic-ref --short HEAD', { silent: true })
    || git('rev-parse --short HEAD', { silent: true })
    || 'HEAD';

  // Detect if the PR is from the upstream repo (not a fork)
  let remoteName = '';
  let isUpstream = false;
  const originUrl = git('remote get-url origin', { silent: true });
  if (originUrl) {
    const normFork = normalizeUrl(forkRepoUrl);
    const normOrigin = normalizeUrl(originUrl);
    if (normFork === normOrigin) {
      remoteName = 'origin';
      isUpstream = true;
    }
  }

  let localBranch;
  if (isUpstream) {
    localBranch = forkBranch;
  } else {
    remoteName = forkOwner;
    localBranch = `fork/${forkOwner}/${forkBranch}`;
  }

  console.log(`${c.bold}--- checkout-pr ---${c.reset}`);
  info(`owner:        ${c.bold}${forkOwner}${c.reset}`);
  info(`branch:       ${c.bold}${forkBranch}${c.reset}`);
  info(`repo:         ${c.bold}${forkRepoUrl}${c.reset}`);
  if (isUpstream) {
    info(`upstream:     yes (using remote '${c.bold}${remoteName}${c.reset}')`);
  }
  info(`local branch: ${c.bold}${localBranch}${c.reset}`);
  console.log('');

  // Add remote if needed (skip for upstream PRs)
  if (!isUpstream) {
    const existingUrl = git(`remote get-url "${remoteName}"`, { silent: true });
    if (existingUrl) {
      warn(`remote '${remoteName}' already exists, reusing it`);
    } else {
      info(`adding remote '${remoteName}' \u2192 ${forkRepoUrl}`);
      git(`remote add "${remoteName}" "${forkRepoUrl}"`);
      ok(`remote '${remoteName}' added`);
    }
  }

  // Fetch the branch
  info(`fetching '${forkBranch}' from '${remoteName}'...`);
  const fetchResult = git(`fetch "${remoteName}" "${forkBranch}"`, { silent: true });
  if (fetchResult === null) {
    die(`failed to fetch branch '${forkBranch}' from '${remoteName}' \u2014 check that the fork and branch exist`);
  }
  ok(`fetched latest from '${remoteName}'`);

  // Create or switch to local branch
  const branchExists = git(`show-ref --verify "refs/heads/${localBranch}"`, { silent: true });
  if (branchExists) {
    warn(`branch '${localBranch}' already exists, switching and updating...`);
    git(`checkout "${localBranch}"`);
    git(`reset --hard "refs/remotes/${remoteName}/${forkBranch}"`);
  } else {
    info(`creating branch '${localBranch}'...`);
    git(`checkout -b "${localBranch}" "refs/remotes/${remoteName}/${forkBranch}"`);
  }

  console.log('');
  ok(`ready on branch: ${c.bold}${localBranch}${c.reset}`);
  info(`to switch back:  ${c.bold}git checkout ${previousBranch}${c.reset}`);
}

getReleaseVersionPublishedOn = async function (versionRecord) {
  if (versionRecord.published) {
    return new Date(versionRecord.published);
  }
  // We don't know when the release was published. Luckily, since there is no
  // way to use the tool outside of a release, and we always change the tool
  // between releases, it is a good bet that the release was published on the
  // same day as the tool.
  var toolPackage = versionRecord.tool.split('@');
  var toolName = toolPackage[0];
  var toolVersion = toolPackage[1];
  var toolRecord = await catalog.official.getVersion(toolName, toolVersion);
  if (! toolRecord || ! toolRecord.published) {
    return null;
  }
  return new Date(toolRecord.published);
}

formatHiddenVersions = function (hiddenVersions, oldestShownVersion) {
  // An array of strings, listing the reasons why some versions were hidden.
  var reasons = [];
  // Use our information about hidden versions to figure what reasons we
  // actually want to return to the user.
  if (! oldestShownVersion) {
    // We did not show any versions, so presumably all existing versions of
    // this package are either unmigrated or pre-release versions.
    if (hiddenVersions.lastUnmigrated) {
      reasons.push("unmigrated");
    }
    if (hiddenVersions.lastPreRelease) {
      reasons.push("pre-release");
    }
  } else {
    // If the oldest version on record is older than the oldest shown
    // version, then it was hidden due to MAX_RECENT_VERSION number. (It
    // might also be hidden because it is a pre-release or unmigrated, but
    // age takes priority).
    if (packageVersionParser.lessThan(
        hiddenVersions.oldestVersion, oldestShownVersion)) {
      reasons.push("older");
    }

    // If the latest unmigrated/pre-release version is older than the oldest
    // version that we are showing, then we don't care about it. If it is
    // younger, we need to tell the user.
    //
    // It is certainly possible that, even though a pre-release version is older
    // than the oldest version that we are showing, but under the limit for the
    // MAX_RECENT_VERSIONS. So, in that case, we are eliding that version
    // because it is a pre-release, not because of age. It is still,
    // technically, an 'older' version though, and that explanation is more
    // intuitive.
    if (hiddenVersions.lastPreRelease &&
        packageVersionParser.lessThan(
          oldestShownVersion, hiddenVersions.lastPreRelease)) {
      reasons.push("pre-release");
    }
    if (hiddenVersions.lastUnmigrated &&
        packageVersionParser.lessThan(
          oldestShownVersion, hiddenVersions.lastUnmigrated)) {
      reasons.push("unmigrated");
    }
  }

  // Now, we will aggregate the reasons into a human-readable string.
  if (reasons.length === 1) {
    return reasons[0];
  } else if (reasons.length === 2) {
    // There is no oxford comma if only listing two objects
    return reasons[0] + " and " + reasons[1];
  } else if (reasons.length > 2)  {
    return reasons.slice(0, -1).join(", ") + ", and " + _.last(reasons);
  } else {
    // Did we not figure out anything to write? Did something else go wrong?
    // This should never happen, but if it does, recover by omitting
    // information.
    return "Some";
  }
}

