async function getChildProcess({ isFirstTry }) {
  if (typeof devBundleBinCommand !== "string") {
    return Promise.resolve(null);
  }

  const helpers = require("./dev-bundle-bin-helpers");

  const [devBundleDir, env] = await Promise.all([
    getDevBundleDir(),
    getEnv()
  ]);

  if (isFirstTry && devBundleDir === DEFAULT_DEV_BUNDLE_DIR) {
    return null
  }

  const cmd = helpers.getCommand(devBundleBinCommand, devBundleDir);

  if (!cmd) {
    return null;
  }

  const child = require('child_process').spawn(cmd, args, {
    stdio: 'inherit',
    env: env,
    shell: process.platform === 'win32' && ['.cmd', '.bat'].some(_extension => cmd.endsWith(_extension)),
  });
  require("./flush-buffers-on-exit-in-windows");
  child.on("error", function (error) {
    console.log(error.stack || error);
  });
  child.on("exit", function (exitCode) {
    process.exit(exitCode);
  });
  return child;
}

function getCommand (name, devBundleDir) {
  let result = null;

  // Strip leading and/or trailing whitespace.
  name = name.replace(/^\s+|\s+$/g, "");

  if (! isValidCommand(name, devBundleDir)) {
    return result;
  }

  extensions.some(function (ext) {
    const cmd = path.join(devBundleDir, "bin", name + ext);
    try {
      if (fs.statSync(cmd).isFile()) {
        result = cmd;
        return true;
      }
    } catch (e) {
      return false;
    }
  });

  return result;
}

function isValidCommand(name, devBundleDir) {
  if (name === "node" ||
      name === "npm" ||
      name === "npx") {
    return true;
  }

  if (! name || name.charAt(0) === ".") {
    // Disallow empty commands and commands that start with a period.
    return false;
  }

  const meteorCommandsJsonPath =
    path.join(devBundleDir, "bin", ".meteor-commands.json");

  try {
    var meteorCommands = require(meteorCommandsJsonPath);
  } catch (e) {
    return false;
  }

  // If `meteor <name>` is already a Meteor command, don't let anything in
  // dev_bundle/bin override it.
  return ! hasOwn.call(meteorCommands, name);
}

async function getEnv(options) {
