    joinArgs[0] = dir;
    const joined = path.join.apply(path, joinArgs);
    if (predicate(joined)) {
      return joined;
    }

    const parentDir = path.dirname(dir);
    if (parentDir === dir) break;
    dir = parentDir;
  }

  return null;
