  }

  const toolsPkg = rel.getToolsPackage();
  const toolsVersion = rel.getToolsVersion();
  const serverArchitectures = await catalog.official.filterArchesWithBuilds(
    toolsPkg,
    toolsVersion,
    archinfo.acceptableMeteorToolArches(),
