    arch,
    sourceRoot,
    buildMode,
    isopackCache,
    linkerCacheDir,
    scannerCacheDir,
    minifyCssResource,
  }) {
    Object.assign(this, {
      unibuilds,
      arch,
      sourceRoot,
      buildMode,
      isopackCache,
      linkerCacheDir,
      scannerCacheDir,
      minifyCssResource,
    });

    if (linkerCacheDir) {
      files.mkdir_p(linkerCacheDir);
    }

    if (scannerCacheDir) {
      files.mkdir_p(scannerCacheDir);
    }
  }

