            meteorInstallOptions: inputFile.meteorInstallOptions,
            absModuleId: inputFile.absModuleId,
            sourceMap: !!(await inputFile.sourceMap),
            mainModule: inputFile.mainModule,
            imported: inputFile.imported,
            alias: inputFile.alias,
            lazy: inputFile.lazy,
            bare: inputFile.bare,
          };
