  // For monorepo, run the meteor command from the app subdirectory
  const appDir = isMonorepo ? path.join(tempDir, 'app') : tempDir;

  // Run the meteor command
  const { meteorProcess, outputLines } = await runMeteorCommand(
    'run', 
    args, 
    appDir,
    {
      captureOutput
    }
  );

